/**
 * The Worker's environment.
 *
 * `Env` is generated by `pnpm run types` from wrangler.example.jsonc into
 * worker-configuration.d.ts. The universe has no secrets.
 *
 * `HOST` is optional and therefore not in the example configuration: the service binding to
 * tau-host (ADR 0013 §6), added by `pnpm run configure --host-service NAME`. Without it the
 * universe cannot bind handles and forwards nothing.
 */

export type UniverseEnv = Env & { HOST?: Fetcher };

/** The one Directory instance every request talks to. */
export const DIRECTORY_NAME = "universe";

export function directoryOf(env: UniverseEnv) {
  return env.DIRECTORY.getByName(DIRECTORY_NAME);
}
